TION public.handle_new_organization()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE\n  v_rows integer;\nBEGIN\n  -- Serie de facturación por defecto\n  INSERT INTO public.factura_series (organization_id, codigo, prefijo, folio_actual, folio_inicial, activa, es_default, descripcion)\n  VALUES (NEW.id, 'A', 'A', 0, 1, true, true, 'Serie por defecto')\n  ON CONFLICT DO NOTHING;\n  GET DIAGNOSTICS v_rows = ROW_COUNT;\n  PERFORM public._log_provisioning_step(NEW.id, 'trigger', 'seed_factura_series', 'factura_series', v_rows);\n\n  -- Pipeline CRM\n  INSERT INTO public.crm_etapas_pipeline (organization_id, nombre, orden, probabilidad_default, color, tipo)\n  VALUES\n    (NEW.id, 'Prospecto',    1, 10,  '#94a3b8', 'abierta'),\n    (NEW.id, 'Calificado',   2, 25,  '#38bdf8', 'abierta'),\n    (NEW.id, 'Propuesta',    3, 50,  '#6366f1', 'abierta'),\n    (NEW.id, 'Negociación',  4, 75,  '#f59e0b', 'abierta'),\n    (NEW.id, 'Ganada',       5, 100, '#10b981', 'ganada'),\n    (NEW.id, 'Perdida',      6, 0,   '#ef4444', 'perdida')\n  ON CONFLICT DO NOTHING;\n  GET DIAGNOSTICS v_rows = ROW_COUNT;\n  PERFORM public._log_provisioning_step(NEW.id, 'trigger', 'seed_crm_etapas_pipeline', 'crm_etapas_pipeline', v_rows);\n\n  -- Motivos de pérdida\n  INSERT INTO public.crm_motivos_perdida (organization_id, nombre)\n  VALUES\n    (NEW.id, 'Precio'),\n    (NEW.id, 'Tiempo de tránsito'),\n    (NEW.id, 'Competencia'),\n    (NEW.id, 'No responde'),\n    (NEW.id, 'Otro')\n  ON CONFLICT DO NOTHING;\n  GET DIAGNOSTICS v_rows = ROW_COUNT;\n  PERFORM public._log_provisioning_step(NEW.id, 'trigger', 'seed_crm_motivos_perdida', 'crm_motivos_perdida', v_rows);\n\n  -- Categorías de presupuesto\n  INSERT INTO public.presupuesto_categorias (organization_id, nombre, orden, tipo_contable)\n  VALUES\n    (NEW.id, 'Ventas',           1, 'Venta'),\n    (NEW.id, 'Costo directo',    2, 'CostoDirectoEmbarque'),\n    (NEW.id, 'Administración',   3, 'Administracion')\n  ON CONFLICT DO NOTHING;\n  GET DIAGNOSTICS v_rows = ROW_COUNT;\n  PERFORM public._log_provisioning_step(NEW.id, 'trigger', 'seed_presupuesto_categorias', 'presupuesto_categorias', v_rows);\n\n  RETURN NEW;\nEND;\n$function$\n","function_owner":"postgres","internal":false,"name":"trg_handle_new_organization"},{"definition":"CREATE TRIGGER update_organizations_updated_at BEFORE UPDATE ON organizations FOR EACH ROW EXECUTE FUNCTION update_updated_at_column()","enabled":"O","function_acl":"{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}","function_definition":"CREATE OR REPLACE FUNCTION public.update_updated_at_column()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'public'\nAS $function$\nBEGIN\n  NEW.updated_at = now();\n  RETURN NEW;\nEND;\n$function$\n","function_owner":"postgres","internal":false,"name":"update_organizations_updated_at"}]},{"acl":[{"grantable":false,"grantee":"anon","grantor":"postgres","privilege":"DELETE"},{"grantable":false,"grantee":"anon","grantor":"postgres","privilege":"INSERT"},{"grantable":false,"grantee":"anon","grantor":"postgres","privilege":"MAINTAIN"},{"grantable":false,"grantee":"anon","grantor":"postgres","privilege":"REFERENCES"},{"grantable":false,"grantee":"anon","grantor":"postgres","privilege":"SELECT"},{"grantable":false,"grantee":"anon","grantor":"postgres","privilege":"TRIGGER"},{"grantable":false,"grantee":"anon","grantor":"postgres","privilege":"TRUNCATE"},{"grantable":false,"grantee":"anon","grantor":"postgres","privilege":"UPDATE"},{"grantable":false,"grantee":"authenticated","grantor":"postgres","privilege":"DELETE"},{"grantable":false,"grantee":"authenticated","grantor":"postgres","privilege":"INSERT"},{"grantable":false,"grantee":"authenticated","grantor":"postgres","privilege":"MAINTAIN"},{"grantable":false,"grantee":"authenticated","grantor":"postgres","privilege":"REFERENCES"},{"grantable":false,"grantee":"authenticated","grantor":"postgres","privilege":"SELEC