-- Mantener SELECT/INSERT/UPDATE/DELETE para la administración RLS existente.
REVOKE TRUNCATE, REFERENCES, TRIGGER, MAINTAIN ON TABLE
  public.planes,
  public.navieras,
  public.puertos,
  public.tipos_contenedor,
  public.tipos_cambio_dof
